import numpy as np

def kernel(dst: np.ndarray, src: np.ndarray, dy: int, dx: int) -> np.ndarray:
    out = np.copy(dst)
    sh, sw = src.shape[0], src.shape[1]
    H, W = dst.shape[0], dst.shape[1]

    y0 = -dy if dy < 0 else 0
    if y0 < 0:
        y0 = 0
    y1 = H - dy
    if y1 > sh:
        y1 = sh
    if y1 < 0:
        y1 = 0

    x0 = -dx if dx < 0 else 0
    if x0 < 0:
        x0 = 0
    x1 = W - dx
    if x1 > sw:
        x1 = sw
    if x1 < 0:
        x1 = 0

    if y0 < y1 and x0 < x1:
        dy0 = dy + y0
        dx0 = dx + x0
        out[dy0:dy0 + y1 - y0, dx0:dx0 + x1 - x0] = src[y0:y1, x0:x1]
    return out
